package io.mavsdk.kotlin.plugins.mavlink_direct_server

import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow

/**
 * Enable direct MAVLink communication using libmav from a server component.
 *
 * Unlike MavlinkDirect, this does not require a discovered system: it sends from the local server
 * component, which makes it suitable for broadcasting messages (e.g. as an autopilot or custom
 * component) without a connected counterpart.
 */
class MavlinkDirectServer internal constructor(private val native: MavlinkDirectServerNative) {
    private var closed = false

    /** Possible results returned for action requests. */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request succeeded */
        SUCCESS(1),
        /** Error */
        ERROR(2),
        /** Invalid MAVLink message */
        INVALID_MESSAGE(3),
        /** Invalid field name or value */
        INVALID_FIELD(4),
        /** Connection error */
        CONNECTION_ERROR(5),
        /** No system connected */
        NO_SYSTEM(6),
        /** Request timed out */
        TIMEOUT(7);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /**
     * A complete MAVLink message with all header information and fields
     *
     * @property messageName MAVLink message name (e.g., "HEARTBEAT", "GLOBAL_POSITION_INT")
     * @property systemId System ID of the sender (for received messages)
     * @property componentId Component ID of the sender (for received messages)
     * @property targetSystemId Target system ID (for sending, 0 for broadcast)
     * @property targetComponentId Target component ID (for sending, 0 for broadcast)
     * @property fieldsJson All message fields as single JSON object
     */
    data class MavlinkMessage(
        val messageName: String,
        val systemId: Int,
        val componentId: Int,
        val targetSystemId: Int,
        val targetComponentId: Int,
        val fieldsJson: String,
    )

    /**
     * Send a MAVLink message directly.
     *
     * This allows sending any MAVLink message with full control over the message content. Leave
     * target_system_id and target_component_id at 0 to broadcast.
     *
     * @param message The MAVLink message to send
     * @return The result of the request.
     */
    fun sendMessage(message: MavlinkMessage): Result = Result.fromValue(native.sendMessage(message))

    /**
     * Subscribe to incoming MAVLink messages.
     *
     * This provides direct access to incoming MAVLink messages. Use an empty string in message_name
     * to subscribe to all messages, or specify a message name (e.g., "HEARTBEAT") to filter for
     * specific message types. Unlike the MavlinkDirect (client) plugin, this is not scoped to a
     * single system: it receives matching messages from all systems.
     *
     * @param messageName MAVLink message name to filter for (e.g., "HEARTBEAT"), empty string = all
     *   messages
     * @return The received MAVLink message
     */
    fun subscribeMessage(messageName: String): Flow<MavlinkMessage> = callbackFlow {
        val subscriptionHandle = native.subscribeMessage(messageName) { value -> trySend(value) }
        awaitClose { native.unsubscribeMessage(subscriptionHandle) }
    }

    /**
     * Load custom MAVLink message definitions from XML.
     *
     * This allows loading custom MAVLink message definitions at runtime, extending the available
     * message types beyond the built-in definitions.
     *
     * @param xmlContent The custom MAVLink XML definition content
     * @return The result of the request.
     */
    fun loadCustomXml(xmlContent: String): Result =
        Result.fromValue(native.loadCustomXml(xmlContent))

    /**
     * Subscribe to incoming commands with a given command ID.
     *
     * Delivers COMMAND_LONG and COMMAND_INT messages with this command ID that are addressed to
     * this server component; check message_name to see which one it is.
     *
     * While subscribed, MAVSDK does not ack the command itself, so every command received must be
     * answered by sending a COMMAND_ACK with SendMessage, addressed to the sender
     * (system_id/component_id of the received command) and with "command" set to the command ID.
     * For a command that takes a while, send acks with MAV_RESULT_IN_PROGRESS and "progress" in
     * percent (255 if unknown) about once per second while it runs, so the sender knows it is still
     * going, then the final result.
     *
     * The sender may retransmit the command if the ack is lost, so the same command can arrive more
     * than once.
     *
     * @param command MAV_CMD to subscribe to
     * @return The received COMMAND_LONG or COMMAND_INT
     */
    fun subscribeCommand(command: Int): Flow<MavlinkMessage> = callbackFlow {
        val subscriptionHandle = native.subscribeCommand(command) { value -> trySend(value) }
        awaitClose { native.unsubscribeCommand(subscriptionHandle) }
    }

    internal fun destroy() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class MavlinkDirectServerException(val result: Result, message: String) : Exception(message)
}

internal interface MavlinkDirectServerNative {
    fun sendMessage(message: MavlinkDirectServer.MavlinkMessage): Int

    fun subscribeMessage(
        messageName: String,
        callback: (MavlinkDirectServer.MavlinkMessage) -> Unit,
    ): Long

    fun unsubscribeMessage(subscriptionHandle: Long)

    fun loadCustomXml(xmlContent: String): Int

    fun subscribeCommand(command: Int, callback: (MavlinkDirectServer.MavlinkMessage) -> Unit): Long

    fun unsubscribeCommand(subscriptionHandle: Long)

    fun destroy()
}

internal expect fun createMavlinkDirectServerNative(systemHandle: Long): MavlinkDirectServerNative
